    write(Path(floor_path),floor); write(Path(completion_path),completion); write(Path(auth_path),auth_binding); write(Path(frontier_path),frontier_binding); write(Path(instruction_path),instruction); write(Path(transition_path),transition); write(Path(qa_path),qa); write(Path(gate_path),gate); write(Path(state_path),state); write(Path("registries/implementation/grt_v0_2/CURRENT_STATE_POINTER.json"),pointer)
